import pyomo.environ as pyo

DATA = {
    "services": ["internet", "tv"],
    "resources": ["wiring", "box"],
    "profit": {"internet": 100, "tv": 120},
    "usage": {
        "wiring": {"internet": 60, "tv": 50},
        "box": {"internet": 10, "tv": 20},
    },
    "availability": {"wiring": 7000, "box": 4000},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.SERVICES = pyo.Set(initialize=d["services"])
    model.RESOURCES = pyo.Set(initialize=d["resources"])

    model.install = pyo.Var(
        model.SERVICES,
        within=pyo.NonNegativeIntegers,
    )

    def obj_rule(m):
        return sum(d["profit"][s] * m.install[s] for s in m.SERVICES)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def resource_rule(m, r):
        return sum(
            d["usage"][r][s] * m.install[s] for s in m.SERVICES
        ) <= d["availability"][r]

    model.resource_capacity = pyo.Constraint(
        model.RESOURCES, rule=resource_rule
    )

    return model
